import it.unimi.dsi.fastutil.objects.Reference2IntOpenHashMap;
import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.Nullable;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static com.gregtechceu.gtceu.api.machine.multiblock.MultiblockControllerMachine.DEFAULT_STRUCTURE;

public class MultiblockSchemaInfo {

    // spotless:off
    public static final Codec<MultiblockSchemaInfo> CODEC = RecordCodecBuilder.create(instance -> instance.group(
            MultiblockMachineDefinition.CODEC.fieldOf("definition").forGetter(MultiblockSchemaInfo::getDefinition),
            GTCodecUtils.map(Codec.INT, Codec.INT).fieldOf("userSliceRepeats").forGetter(MultiblockSchemaInfo::getUserSliceRepeats),
            Codec.INT.listOf().fieldOf("userDimensions").forGetter(MultiblockSchemaInfo::getUserDimensions),
            GTCodecUtils.map(BlockPos.CODEC, BlockInfo.CODEC).fieldOf("userGlobalBlockPreferences").forGetter(MultiblockSchemaInfo::getUserGlobalBlockPreferences),
            GTCodecUtils.map(SyncSystemCodecs.CHAR, BlockInfo.CODEC).fieldOf("blockPreferences").forGetter(MultiblockSchemaInfo::getBlockPreferences),
            Codec.BOOL.fieldOf("flipped").forGetter(MultiblockSchemaInfo::isFlipped),
            Codec.BOOL.fieldOf("ignorePreviewCount").forGetter(MultiblockSchemaInfo::isIgnorePreviewCount)
    ).apply(instance, MultiblockSchemaInfo::new));
    //spotless:on

    @Getter
    private final MultiblockMachineDefinition definition;
    @Getter
    @Setter
    private SchemaWidget multiSchema;
    @Getter
    @Setter
    private MutableSchema mapSchema;
    @Getter
    @Setter
    private SchemaRenderer renderer;
    @Getter
    @Setter
    private Reference2IntMap<Block> blockCounts = new Reference2IntOpenHashMap<>();
    @Getter
    private final Object2ObjectMap<BlockPos, BlockInfo> userGlobalBlockPreferences;
    @Getter
    @Setter
    private boolean flipped;
    @Getter
    @Setter
    private boolean ignorePreviewCount;
    @Getter
    protected final Char2ObjectMap<BlockInfo> blockPreferences = new Char2ObjectArrayMap<>();
    @Getter
    protected final HashBasedTable<MultiPredicate, BasePredicate, IntIntPair> minMaxPreferences = HashBasedTable
            .create();

    @Getter
    private Int2IntMap userSliceRepeats;
    @Getter
    private final IntList userDimensions;
    @Getter
    private final Map<BlockPos, BlockInfo> structureBlocks = new HashMap<>();

    @Getter
    private @Nullable AbstractStructureHelper structureHelper;

    public MultiblockSchemaInfo(MultiblockMachineDefinition definition) {
        this.definition = definition;
        this.userSliceRepeats = new Int2IntArrayMap();
        this.userDimensions = new IntArrayList();
        this.userGlobalBlockPreferences = new Object2ObjectOpenHashMap<>();
    }

    public MultiblockSchemaInfo(MultiblockMachineDefinition definition, Map<Integer, Integer> userSliceRepeats,
                                List<Integer> userDimensions,
                                Map<BlockPos, BlockInfo> userGlobalBlockPreferences,
                                Map<Character, BlockInfo> blockPreferenceMap,
                                boolean flipped,
                                boolean ignorePreviewCount) {
        this.definition = definition;
        this.flipped = flipped;
        this.ignorePreviewCount = ignorePreviewCount;
        this.userSliceRepeats = new Int2IntArrayMap(userSliceRepeats);
        this.userDimensions = new IntArrayList(userDimensions);
        this.userGlobalBlockPreferences = new Object2ObjectOpenHashMap<>(userGlobalBlockPreferences);
        this.blockPreferences.putAll(blockPreferenceMap);
    }

    @ApiStatus.Internal
    public void refreshSchema(MultiblockMachineDefinition multiblockDefinition, Direction frontFacing,
                              Direction upFacing, boolean isFlipped, @Nullable Runnable onSchemaRefresh) {
        Map<BlockPos, BlockInfo> resultStructure = new HashMap<>();
        IBlockPattern pattern = multiblockDefinition.getStructurePatterns().get(DEFAULT_STRUCTURE).get();

        if (this.structureHelper == null) {
            if (pattern instanceof BlockPattern blockPattern) {
                if (this.userSliceRepeats.isEmpty()) {
                    for (int i = 0; i < blockPattern.getSlices().length; i++) {
                        this.userSliceRepeats.put(i, blockPattern.getSlices()[i].getMinRepeats());
                    }
                }
                // reinterpret slider values as slice repeats?
                this.structureHelper = AbstractStructureHelper.blockPattern(this.userSliceRepeats);

            } else if (pattern instanceof ExpandablePattern expandablePattern) {
                if (this.userDimensions.isEmpty()) {
                    expandablePattern.getBoundsConstraints().apply().stream()
                            .mapToInt(Pair::left)
                            .forEach(this.userDimensions::add);
                }
                // reinterpret slider values as bounds?
                this.structureHelper = AbstractStructureHelper.expandable(this.userDimensions);

            } else {
                // throw? log?
                return;
            }
        }

        this.structureHelper.populate(this, resultStructure, pattern, this.userGlobalBlockPreferences,
                frontFacing, upFacing, isFlipped);

        Long2ReferenceMap<BlockState> schemaMap = new Long2ReferenceOpenHashMap<>();
        this.blockCounts.clear();
        for (var entry : resultStructure.entrySet()) {
            BlockState state = entry.getValue().getBlockState();
            schemaMap.put(entry.getKey().asLong(), state);
            if (state.isAir()) continue;
            this.blockCounts.merge(state.getBlock(), 1, Integer::sum);
        }
        if (this.mapSchema == null) {
            this.mapSchema = new MutableSchema(schemaMap);
        } else {
            this.mapSchema.setBlocks(schemaMap);
        }
        this.structureBlocks.clear();
        this.structureBlocks.putAll(resultStructure);

        if (onSchemaRefresh != null) {
            onSchemaRefresh.run();
        }
    }
}

package com.gregtechceu.gtceu.api.sync_system;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformer;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformers;
import com.gregtechceu.gtceu.api.sync_system.managed.ISyncManaged;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;

import io.netty.buffer.Unpooled;
import it.unimi.dsi.fastutil.objects.ObjectOpenHashSet;
import it.unimi.dsi.fastutil.objects.ObjectSet;
import lombok.Setter;
import org.jetbrains.annotations.Nullable;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.WrongMethodTypeException;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Class that holds all sync info for an {@link ISyncManaged} object.
 */
public class SyncDataHolder {

    private final ClassSyncData syncData;
    private final ISyncManaged holder;

    private final ObjectSet<String> dirtySyncFields = new ObjectOpenHashSet<>();
    @Setter
    private boolean hasDirtyChildSyncObject = false;
    private boolean resyncAll = false;

    public SyncDataHolder(ISyncManaged o) {
        holder = o;
        syncData = ClassSyncData.getClassData(o.getClass());
    }

    /**
     * Instructs the sync system that this field has been updated and must be synced with clients.
     * 
     * @param fieldName The field that has changed.
     */
    public void markClientSyncFieldDirty(String fieldName) {
        dirtySyncFields.add(fieldName);
        holder.markAsChanged();
    }

    public void resyncAllFields() {
        resyncAll = true;
        holder.markAsChanged();
    }

    public boolean needsSync() {
        return !dirtySyncFields.isEmpty() || resyncAll || hasDirtyChildSyncObject;
    }

    @SuppressWarnings("unchecked")
    public CompoundTag serializeNBT(HolderLookup.Provider lookup) {
        CompoundTag tag = new CompoundTag();
        for (var field : syncData.getServerSaveFields().values()) {
            Object currentValue = field.handle.get(holder);
            if (currentValue == null || !confirmTransformerPresent(field, holder)) continue;

            try {
                Tag nbtValue = ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .serializeNBT(currentValue,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        false, false, lookup));
                tag.put(field.nbtSaveKey, nbtValue);

            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to serialize field {}", field.fieldName, e);
            }
        }
        return tag;
    }

    @SuppressWarnings("unchecked")
    public void deserializeNBT(HolderLookup.Provider lookup, CompoundTag tag) {
        for (var field : syncData.getServerSaveFields().values()) {
            Tag newValue = tag.get(field.nbtSaveKey);
            if (newValue == null || newValue instanceof CompoundTag compound &&
                    (compound.isEmpty() || (compound.size() == 1 && compound.getBoolean("null"))))
                continue;

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                ValueTransformer<Object> transformer = (ValueTransformer<Object>) field.transformer;
                var current = field.handle.get(holder);

                Object result = Objects.requireNonNull(transformer).deserializeNBT(newValue,
                        new ValueTransformer.TransformerContext<>(
                                holder, field.type, current, field.fieldName, false, false, lookup));

                if (result != current) trySetField(field, holder, result);

            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to deserialize field {}", field.fieldName, e);
            }
        }
    }

    @SuppressWarnings("unchecked")
    public void writeClientPacket(HolderLookup.Provider lookup, FriendlyByteBuf buf) {
        Set<FieldSyncData> fieldsToSerialize = syncData.getClientSyncFields().values().stream()
                .filter(this::shouldSyncFieldToClient).collect(Collectors.toSet());

        var fieldData = new FriendlyByteBuf(Unpooled.buffer());
        boolean hadErrorWritingData = false;

        for (var field : fieldsToSerialize) {
            Object currentValue = field.handle.get(holder);

            fieldData.writeUtf(field.fieldName);
            fieldData.writeBoolean(currentValue == null);
            if (currentValue == null) continue;

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .writeToPacket(fieldData, currentValue,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        true, resyncAll, lookup));
            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to write client packet on field {}", field.fieldName, e);
                hadErrorWritingData = true;
                break;
            }
        }

        resyncAll = false;
        dirtySyncFields.clear();
        hasDirtyChildSyncObject = false;

        if (hadErrorWritingData) {
            buf.writeVarInt(0);
            return;
        }

        buf.writeVarInt(fieldsToSerialize.size());
        buf.writeBytes(fieldData);
    }

    @SuppressWarnings("unchecked")
    public void readClientPacket(HolderLookup.Provider lookup, FriendlyByteBuf buf) {
        int fieldsToRead = buf.readVarInt();

        for (int fieldIndex = 0; fieldIndex < fieldsToRead; fieldIndex++) {
            String fieldName = buf.readUtf();
            FieldSyncData field = syncData.getClientSyncFields().get(fieldName);

            if (field == null) {
                GTCEu.LOGGER.error("Sync: Failed to read client packet: Unknown field {}", fieldName);
                return;
            }

            Object currentValue = field.handle.get(holder);

            boolean isNull = buf.readBoolean();
            if (isNull) {
                trySetField(field, holder, null);
                executeClientsideUpdateCallbacks(field);
                continue;
            }

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                Object result = ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .readFromPacket(buf,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        true, resyncAll, lookup));

                if (result != currentValue) {
                    trySetField(field, holder, result);
                }
                executeClientsideUpdateCallbacks(field);
            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to read client packet on field {}", field.fieldName, e);
                return;
            }

        }
    }

    private boolean shouldSyncFieldToClient(FieldSyncData field) {
        return (resyncAll || dirtySyncFields.contains(field.fieldName) ||
                field.handle.get(holder) instanceof ISyncManaged syncManaged &&
                        syncManaged.getSyncDataHolder().needsSync());
    }

    private void executeClientsideUpdateCallbacks(FieldSyncData field) {
        try {
            for (MethodHandle changeListenerHandle : field.changeListenerHandles) {
                changeListenerHandle.invoke(holder);
            }
        } catch (Throwable e) {
            if (e instanceof WrongMethodTypeException) {
                throw new IllegalArgumentException(
                        "Invalid method signature for change listener for field %s %s"
                                .formatted(field.fieldName, holder.getClass().getName()));
            }
            GTCEu.LOGGER.error("Sync: Error while invoking change listener for field {}", field.fieldName, e);
        }

        if (field.triggerClientRerender) holder.scheduleRenderUpdate();
    }

    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    private static boolean confirmTransformerPresent(FieldSyncData field, Object holder) {
        if (field.transformer == null) {
            field.setTransformer(ValueTransformers.get(field.type.getRawType()));
            if (field.transformer == null) {
                GTCEu.LOGGER.error(
                        "Sync: Failed to serialize/deserialize field {} in class {}: Missing value transformer for {}",
                        field.fieldName, holder.getClass().getName(), field.type);
                return false;
            }
        }
        return true;
    }

    private static void trySetField(FieldSyncData field, Object holder, @Nullable Object value) {
        try {
            field.handle.set(holder, value);
        } catch (Exception e) {
            if (e instanceof UnsupportedOperationException) {
                GTCEu.LOGGER.error(
                        "Sync: failed to perform VarHandle set: unsupported op on {} (you are probably trying to sync a final field)",
                        field.fieldName);
                return;
            }
            GTCEu.LOGGER.error("Sync: Failed to perform VarHandle set on {} : {}", field.fieldName, e);
        }
    }

    public static class SyncManagedTransformer implements ValueTransformer<ISyncManaged> {

        @Override
        public Tag serializeNBT(ISyncManaged value, TransformerContext<ISyncManaged> context) {
            return value.getSyncDataHolder().serializeNBT(context.lookup());
        }

        @Override
        public @Nullable ISyncManaged deserializeNBT(Tag tag, TransformerContext<ISyncManaged> context) {
            ISyncManaged syncManaged = context.currentValue();

            if (syncManaged == null) {
                GTCEu.LOGGER.error("Sync: ISyncManaged field was null, cannot instantiate {}",
                        context.fieldName());
                return null;
            }

            syncManaged.getSyncDataHolder().deserializeNBT(context.lookup(), (CompoundTag) tag);
            return syncManaged;
        }

        @Override
        public void writeToPacket(FriendlyByteBuf buf, ISyncManaged value, TransformerContext<ISyncManaged> context) {
            if (context.isClientFullSyncUpdate()) value.getSyncDataHolder().resyncAllFields();
            value.getSyncDataHolder().writeClientPacket(context.lookup(), buf);
        }

        @Override
        public @Nullable ISyncManaged readFromPacket(FriendlyByteBuf buf, TransformerContext<ISyncManaged> context) {
            ISyncManaged syncManaged = context.currentValue();
            var clazz = context.type().getClassValue();

            if (syncManaged == null && clazz != null && ISyncManaged.class.isAssignableFrom(clazz)) {
                var ctor = ClassSyncData.getClassData(clazz).getClientsideConstructor();
                if (ctor != null) syncManaged = (ISyncManaged) ctor.get();
            }

            if (syncManaged == null) {
                GTCEu.LOGGER.error("Sync: ISyncManaged field was null on client, cannot instantiate {}",
                        context.fieldName());
                return null;
            }

            syncManaged.getSyncDataHolder().readClientPacket(context.lookup(), buf);
            return syncManaged;
        }
    }
}

package com.gregtechceu.gtceu.api.sync_system.data_transformers;

import com.gregtechceu.gtceu.GTCEu;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraftforge.common.util.INBTSerializable;

import javax.annotation.Nullable;

public class NBTSerializableTransformer implements ValueTransformer<INBTSerializable<Tag>> {

    @Override
    public Tag serializeNBT(INBTSerializable<Tag> value,
                            ValueTransformer.TransformerContext<INBTSerializable<Tag>> context) {
        return value.serializeNBT();
    }

    @Override
    public @Nullable INBTSerializable<Tag> deserializeNBT(Tag tag,
                                                          ValueTransformer.TransformerContext<INBTSerializable<Tag>> context) {
        var currentVal = context.currentValue();
        if (currentVal == null) {
            GTCEu.LOGGER.warn(
                    "Sync: Deserialization of INBTSerializable objects requires an existing object, they cannot be instantiated purely from saved data.");
            return null;
        }
        currentVal.deserializeNBT(tag);
        return currentVal;
    }

    private static final String WRAPPED_TAG_KEY = "$$field$$";

    @Override
    public void writeToPacket(FriendlyByteBuf buf, INBTSerializable<Tag> value,
                              TransformerContext<INBTSerializable<Tag>> context) {
        Tag data = value.serializeNBT();
        if (data instanceof CompoundTag compoundTag) {
            buf.writeNbt(compoundTag);
        } else {
            CompoundTag wrapper = new CompoundTag();
            wrapper.put(WRAPPED_TAG_KEY, data);
            buf.writeNbt(wrapper);
        }
    }

    @Override
    public @Nullable INBTSerializable<Tag> readFromPacket(FriendlyByteBuf buf,
                                                          TransformerContext<INBTSerializable<Tag>> context) {
        var currentVal = context.currentValue();
        Tag read = buf.readNbt();
        if (read instanceof CompoundTag compound && compound.size() == 1 && compound.contains(WRAPPED_TAG_KEY)) {
            read = compound.get(WRAPPED_TAG_KEY);
        }
        if (currentVal == null) {
            GTCEu.LOGGER.warn(
                    "Sync: Deserialization of INBTSerializable objects requires an existing object, they cannot be instantiated purely from a client packet.");
            return null;
        }
        if (read != null) currentVal.deserializeNBT(read);
        return currentVal;
    }
}

package com.gregtechceu.gtceu.api.sync_system.managed;

import com.gregtechceu.gtceu.api.blockentity.BlockEntityCreationInfo;
import com.gregtechceu.gtceu.api.registry.GTRegistries;
import com.gregtechceu.gtceu.api.sync_system.SyncDataHolder;

import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.Connection;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;

import io.netty.buffer.Unpooled;
import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.MustBeInvokedByOverriders;
import org.jetbrains.annotations.Nullable;

import java.util.Objects;

/**
 * A BlockEntity that manages sync and save data via the {@code ISyncManaged} syncdata system.
 * 
 * @see ISyncManaged
 */
public abstract class ManagedSyncBlockEntity extends BlockEntity implements ISyncManaged {

    @Getter
    protected final SyncDataHolder syncDataHolder = new SyncDataHolder(this);
    @Getter
    @Setter
    private boolean isDirty;

    public ManagedSyncBlockEntity(BlockEntityCreationInfo info) {
        super(info.type(), info.pos(), info.state());
    }

    public ManagedSyncBlockEntity(BlockEntityType<?> type, BlockPos pos, BlockState blockState) {
        super(type, pos, blockState);
    }

    /**
     * Saves BE data to world save.
     */
    @Override
    protected final void saveAdditional(CompoundTag tag) {
        super.saveAdditional(tag);
        tag.merge(getSyncDataHolder().serializeNBT(getHolderLookup()));
    }

    /**
     * Loads BE data from world save.<br>
     * Override this to add logic for modifying saved data before it is loaded (e.g. for cross-version
     * compatibility).<br>
     * When overriding, {@code super.load(tag)} must be called <b>AFTER</b> any custom logic.
     *
     * @param tag The tag to load
     */
    @Override
    @MustBeInvokedByOverriders
    public void load(CompoundTag tag) {
        super.load(tag);
        getSyncDataHolder().deserializeNBT(getHolderLookup(), tag);
    }

    @Override
    public final void handleUpdateTag(CompoundTag tag) {
        byte[] data = tag.getByteArray("data");
        getSyncDataHolder().readClientPacket(getHolderLookup(), new FriendlyByteBuf(Unpooled.wrappedBuffer(data)));
    }

    @Override
    public final void onDataPacket(Connection net, ClientboundBlockEntityDataPacket pkt) {
        CompoundTag tag = pkt.getTag();
        if (tag != null) {
            byte[] data = tag.getByteArray("data");
            getSyncDataHolder().readClientPacket(getHolderLookup(), new FriendlyByteBuf(Unpooled.wrappedBuffer(data)));
        }
    }

    /**
     * Called to gather BE data to be sent when a client loads this BE.
     */
    @Override
    public CompoundTag getUpdateTag() {
        return writeClientPacket(true);
    }

    /**
     * Called to get an update packet which is sent to clients to notify them when a loaded BE's data changes.
     */
    @Override
    public @Nullable Packet<ClientGamePacketListener> getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this, b -> writeClientPacket(false));
    }

    private CompoundTag writeClientPacket(boolean fullSync) {
        var stream = new FriendlyByteBuf(Unpooled.buffer());
        if (fullSync) getSyncDataHolder().resyncAllFields();
        getSyncDataHolder().writeClientPacket(getHolderLookup(), stream);

        stream.capacity(stream.readableBytes());
        CompoundTag data = new CompoundTag();
        data.putByteArray("data", stream.array());
        return data;
    }

    private HolderLookup.Provider getHolderLookup() {
        Level level = getLevel();
        return level == null ? GTRegistries.builtinRegistry() : level.registryAccess();
    }

    @Override
    public @Nullable ISyncManaged getParentSyncObject() {
        return null;
    }

    @Override
    public final void markAsChanged() {
        isDirty = true;
    }

    @Override
    public void setChanged() {
        if (getLevel() != null) {
            getLevel().blockEntityChanged(getBlockPos());
        }
    }

    /**
     * Called each tick on the server side.
     */
    @MustBeInvokedByOverriders
    public void serverTick() {
        setChanged();
        if (isDirty) {
            Objects.requireNonNull(getLevel()).sendBlockUpdated(getBlockPos(), getBlockState(), getBlockState(),
                    Block.UPDATE_CLIENTS);
            isDirty = false;
        }
    }

    /**
     * Called each tick on the client side.
     */
    public void clientTick() {}
}

package com.gregtechceu.gtceu.api.transfer.item;

import net.minecraft.core.BlockPos;
import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraftforge.common.util.INBTSerializable;
import net.minecraftforge.items.ItemStackHandler;

import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.NotNull;

import java.util.function.Predicate;

public class CustomItemStackHandler extends ItemStackHandler
                                    implements INBTSerializable<CompoundTag> {

    @Getter
    @Setter
    protected @NotNull Runnable onContentsChanged = () -> {};
    @Getter
    @Setter
    protected Predicate<ItemStack> filter = stack -> true;

    public CustomItemStackHandler() {
        super();
    }

    public CustomItemStackHandler(int size) {
        super(size);
    }

    public CustomItemStackHandler(ItemStack itemStack) {
        this(NonNullList.of(ItemStack.EMPTY, itemStack));
    }

    public CustomItemStackHandler(NonNullList<ItemStack> stacks) {
        super(stacks);
    }

    @Override
    public boolean isItemValid(int slot, @NotNull ItemStack stack) {
        return filter.test(stack);
    }

    @Override
    public void onContentsChanged(int slot) {
        onContentsChanged.run();
    }

    public void clear() {
        stacks.clear();
        onContentsChanged.run();
    }

    public NonNullList<ItemStack> toList() {
        NonNullList<ItemStack> list = NonNullList.create();
        for (int slot = 0; slot < getSlots(); slot++) list.add(getStackInSlot(slot));
        return list;
    }

    public void dropInventoryInWorld(Level world, BlockPos pos) {
        for (ItemStack stack : stacks) {
            Block.popResource(world, pos, stack);
        }
        clear();
    }

    @Override
    public void deserializeNBT(CompoundTag nbt) {
        if (nbt.getInt("Size") != stacks.size()) nbt.putInt("Size", stacks.size());
        super.deserializeNBT(nbt);
    }
}

package com.gregtechceu.gtceu.common.entity;

import com.gregtechceu.gtceu.common.data.GTEntityTypes;
import com.gregtechceu.gtceu.common.data.GTItems;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundAddEntityPacket;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.vehicle.Boat;
import net.minecraft.world.entity.vehicle.ChestBoat;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.Level;

public class GTChestBoat extends ChestBoat {

    public GTChestBoat(EntityType<? extends Boat> entityType, Level level) {
        super(entityType, level);
        this.blocksBuilding = true;
    }

    public GTChestBoat(Level level, double x, double y, double z) {
        super(GTEntityTypes.CHEST_BOAT.get(), level);
        this.setPos(x, y, z);
        this.xo = x;
        this.yo = y;
        this.zo = z;
    }

    @Override
    public Packet<ClientGamePacketListener> getAddEntityPacket() {
        return new ClientboundAddEntityPacket(this);
    }

    @Override
    protected void addAdditionalSaveData(CompoundTag compound) {
        compound.putString("Type", getBoatType().getName());
    }

    @Override
    protected void readAdditionalSaveData(CompoundTag compound) {
        if (compound.contains("Type")) {
            entityData.set(DATA_ID_TYPE, GTBoat.BoatType.byName(compound.getString("Type")).ordinal());
        }
    }

    @Override
    public Item getDropItem() {
        return switch (GTBoat.BoatType.byId(this.entityData.get(DATA_ID_TYPE))) {
            case RUBBER -> GTItems.RUBBER_CHEST_BOAT.get();
            case TREATED_WOOD -> GTItems.TREATED_WOOD_CHEST_BOAT.get();
        };
    }

    public void setBoatType(GTBoat.BoatType type) {
        this.entityData.set(DATA_ID_TYPE, type.ordinal());
    }

    public GTBoat.BoatType getBoatType() {
        return GTBoat.BoatType.byId(entityData.get(DATA_ID_TYPE));
    }

    @Override
    public void setVariant(Type variant) {}

    @Override
    public Type getVariant() {
        return Type.OAK;
    }
}

